const postText = items[0].json.data.editedPost
  .replace(/[\r\n]+/g, ' ')
  .trim();

const escaped = JSON.stringify(postText);

const body = `{"author":"urn:li:person:YOUR_PERSON_URN","lifecycleState":"PUBLISHED","specificContent":{"com.linkedin.ugc.ShareContent":{"shareCommentary":{"text":${escaped}},"shareMediaCategory":"NONE"}},"visibility":{"com.linkedin.ugc.MemberNetworkVisibility":"PUBLIC"}}`;

return [{ json: { body: body } }];
